from typing import Sequence

def composite_summary(orbits: Sequence[int]) -> dict[str, int]:
    if not orbits or any(q < 1 for q in orbits):
        raise ValueError("Orbit counts must be positive")
    q = sum(orbits)
    return {"orbits": q, "vertices": 2*q, "coindex": q-1, "faces": 3**q}

if __name__ == "__main__":
    factors = [2, 3, 5]
    result = composite_summary(factors)
    print(f"Factors {factors} produce {result}")
    assert result["coindex"] == 9 and result["vertices"] == 20

from itertools import product
from typing import Iterator

def faces(axis_count: int) -> Iterator[tuple[int, ...]]:
    if axis_count < 1:
        raise ValueError("axis_count must be positive")
    yield from product((-1, 0, 1), repeat=axis_count)

if __name__ == "__main__":
    for q in range(1, 7):
        count = sum(1 for _ in faces(q))
        print(f"{q} axes: {count} faces, co-index {q-1}")
        assert count == 3**q

