from typing import Mapping, Hashable, TypeVar
T = TypeVar("T", bound=Hashable)

def coindex_from_involution(anti: Mapping[T, T]) -> int:
    vertices = set(anti)
    if not vertices:
        raise ValueError("The system must be nonempty")
    for v in vertices:
        if anti[v] == v or anti.get(anti[v]) != v:
            raise ValueError("The map is not a fixed-point-free involution")
    return len(vertices) // 2 - 1

from typing import Iterable

def finite_join_coindex(coindices: Iterable[int]) -> int:
    values = list(coindices)
    if not values or any(c < 0 for c in values):
        raise ValueError("Expected a nonempty list of natural numbers")
    shifted_total = 0
    for coindex in values:
        shifted_total += coindex + 1
    return shifted_total - 1

from typing import Sequence

def audit_composite(coindices: Sequence[int], vertex_counts: Sequence[int]) -> bool:
    if len(coindices) != len(vertex_counts) or not coindices:
        return False
    local = all(c >= 0 and n > 0 and 2*(c+1) == n
                for c, n in zip(coindices, vertex_counts))
    global_check = 2*sum(c+1 for c in coindices) == sum(vertex_counts)
    return local and global_check

